(() => {
'use strict';
const D=window.AE48_DATA, main=document.getElementById('main'),dialog=document.getElementById('detail');
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18m-13 4h2m4 0h2"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-2a6 6 0 0 1 12 0v2m1-16a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 4v2"/>',file:'<path d="M14 3H6a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9zm0 0v6h6M8 13h8m-8 4h5"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v4h16v-4"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',chevron:'<path d="m9 5 7 7-7 7"/>',sport:'<ellipse cx="14.5" cy="8.5" rx="5" ry="7" transform="rotate(40 14.5 8.5)"/><path d="m10 14-6 7m9-18 6 6m-9-2 7 7m-6-10-2 9m7-10-3 12"/>',food:'<path d="M5 3v7a2 2 0 0 0 4 0V3m-2 0v18m11-18c-3 3-4 6-4 10h4m0-10v18"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',check:'<path d="m5 12 4 4L19 6"/>',copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.file}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('vi-VN').format(Math.abs(n))+' ₫';
const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/đ/g,'d');
const stamp=new Intl.DateTimeFormat('vi-VN',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',timeZone:D.timezone}).format(new Date(D.updatedAt));
let state={page:'overview',member:'all',query:'',status:'all',category:'all',collection:'open'};
try{const saved=localStorage.getItem('ae48-person');if(saved==='all'||D.members.some(m=>m.id===saved))state.member=saved;}catch{}
const initials=n=>n.split(' ').slice(-2).map(s=>s[0]).join('').toUpperCase();
const avatar=m=>`<span class="avatar tone${Number(m.id.slice(1))%5}" aria-hidden="true">${esc(initials(m.name))}</span>`;
const statusBadge=m=>m.balance>0?'<span class="badge owe">Cần đóng</span>':m.balance<0?'<span class="badge credit">Được nhận</span>':'<span class="badge">Không phát sinh</span>';
const sessionStatus=s=>s.issues.length?'Cần kiểm tra':s.pending?'Chờ hóa đơn':s.collected?'Đã collect theo Excel':'Chưa collect';
const date=s=>s.date?new Intl.DateTimeFormat('vi-VN',{day:'2-digit',month:'2-digit',year:'numeric',timeZone:'UTC'}).format(new Date(s.date+'T00:00:00Z')):'Chưa có ngày';
const openSessions=()=>D.sessions.filter(s=>!s.collected&&!s.pending&&!s.issues.length);
const navItems=[['overview','grid','Tổng quan'],['sessions','calendar','Các buổi'],['members','users','Thành viên'],['payments','check','Đã đóng'],['data','file','Dữ liệu']];
const visibleMembers=()=>D.members.filter(m=>m.balance!==0);
const selected=()=>visibleMembers().find(m=>m.id===state.member);
if(state.member!=='all'&&!selected())state.member='all';
function nav(){document.getElementById('nav').innerHTML=navItems.map(([id,i,label])=>`<a href="#${id}" class="nav-item ${state.page===id?'active':''}" ${state.page===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${id==='sessions'?`<span class="nav-count">${D.openCount}</span>`:''}</a>`).join('');document.getElementById('crumb').textContent=navItems.find(n=>n[0]===state.page)?.[2]||'Tổng quan';document.getElementById('side-date').textContent=stamp+' · TP.HCM';}
const head=(title,sub,exportable=false)=>`<div class="page-head"><div><h1>${title}</h1><p>${sub}</p></div>${exportable?`<button class="button" data-action="export" title="Xuất công nợ CSV" aria-label="Xuất công nợ CSV">${icon('download')}Xuất công nợ</button>`:''}</div>`;
const notice=()=>`<div class="notice">${icon('info')}<div><strong>Bản đối chiếu từ Excel.</strong> ${D.received?'Đã tính khoản đóng và điều chỉnh do admin xác nhận. Các khoản khác giữ theo Excel.':'Công nợ tạm tính; chưa có lịch sử thanh toán từng người.'}</div><button data-action="data">Chi tiết</button></div>`;
function selector(){return `<div class="member-selector"><label for="member-select">Đang xem</label><select id="member-select"><option value="all">Cả nhóm</option>${visibleMembers().map(m=>`<option value="${m.id}" ${state.member===m.id?'selected':''}>${esc(m.name)}${m.guest?' · Khách':''}</option>`).join('')}</select></div>`;}
function hero(){const m=selected();return `<section class="hero" aria-label="Tổng hợp công nợ"><div class="hero-top"><span class="overline">${m?esc(m.name)+' · '+(m.balance<0?'Còn được nhận':m.balance>0?'Cần đóng':'Không phát sinh'):'Tổng chi chưa collect'}</span><span class="tag">Tạm tính từ Excel</span></div><div><div class="hero-value money">${new Intl.NumberFormat('vi-VN').format(m?Math.abs(m.balance):D.total)}<span class="unit">₫</span></div><p class="hero-sub">${m?(m.paid?'Đã trừ '+money(m.paid)+' đã đóng.':'Sau bù trừ phần phải chịu và tiền đã ứng.'):'Cầu lông, ăn uống và những buổi cùng nhau.'}</p></div><div class="hero-bottom">${m?`<span>Phải chịu <strong>${money(m.share)}</strong></span><span>Đã ứng <strong>${money(m.advance)}</strong></span>`:`<span><strong>${D.openCount}</strong> buổi có đủ dữ liệu</span><span><strong>${D.members.filter(m=>m.sessions.length).length}</strong> người liên quan</span>`}</div></section>`;}
function search(placeholder){return `<label class="search">${icon('search')}<input type="search" id="search" placeholder="${placeholder}" aria-label="${placeholder}" value="${esc(state.query)}" autocomplete="off"></label>`;}
function memberList(){const list=visibleMembers().filter(m=>(state.member==='all'||state.page==='members'||m.id===state.member)&&normalize(m.name).includes(normalize(state.query))&&(state.status==='all'||state.status==='owe'&&m.balance>0||state.status==='credit'&&m.balance<0||state.status==='zero'&&m.balance===0)).sort((a,b)=>b.balance-a.balance);
return `<div class="table-scroll"><table><thead><tr><th>Thành viên</th><th class="num hide-mobile">Phải chịu</th><th class="num hide-tablet">Đã ứng</th><th class="num">Công nợ tạm tính</th><th class="hide-mobile">Trạng thái</th></tr></thead><tbody>${list.length?list.map(m=>`<tr><td><button class="person-button" data-person="${m.id}" aria-label="Xem chi tiết ${esc(m.name)}">${avatar(m)}<span class="person-name">${esc(m.name)}<small>${m.guest?'Khách · ':''}${m.sessions.length?m.sessions.length+' buổi'+(m.paid?' · Đã đóng '+money(m.paid):' chưa collect'):'Chưa có phát sinh mở'}</small></span></button></td><td class="num hide-mobile money">${money(m.share)}</td><td class="num hide-tablet money muted">${money(m.advance)}</td><td class="num money ${m.balance<0?'balance-negative':'balance-positive'}">${m.balance<0?'− ':''}${money(m.balance)}<span class="mobile-status">${m.balance<0?'Được nhận':m.balance>0?'Cần đóng':'Không phát sinh'}</span></td><td class="hide-mobile">${statusBadge(m)}</td></tr>`).join(''):`<tr><td colspan="5"><div class="empty">Không tìm thấy thành viên phù hợp.<button class="text-button" data-action="reset">Xóa bộ lọc</button></div></td></tr>`}</tbody></table></div><div class="table-foot"><span>${list.length} người · Dấu − là khoản được nhận</span><span>Chạm vào tên để xem chi tiết</span></div>`;}
function memberPanel(){return `<div class="panel"><div class="toolbar">${search('Tìm thành viên…')}<div class="segment" role="group" aria-label="Lọc công nợ">${[['all','Tất cả'],['owe','Cần đóng'],['credit','Được nhận']].map(([k,t])=>`<button data-status="${k}" class="${state.status===k?'active':''}" aria-pressed="${state.status===k}">${t}</button>`).join('')}</div></div><div id="member-results">${memberList()}</div></div>`;}
function sessionRow(s,card=false){return `<button class="session-row" data-session="${s.id}" aria-label="Xem ${esc(s.id+' '+s.title)}"><span class="category-icon ${s.category}">${icon(s.category==='sport'?'sport':'food')}</span><span><span class="session-title">${esc(s.title)}</span><span class="session-meta" style="display:block">${s.id} <span aria-hidden="true">·</span> ${s.participants.length} người <span aria-hidden="true">·</span> ${card?date(s):(s.category==='sport'?'Cầu lông':'Ăn uống')}</span></span><span class="session-value money">${s.pending?'Chờ bill':money(s.total)}<small ${s.issues.length?'style="color:var(--amber)"':''}>${s.issues.length?'Cần kiểm tra':s.pending?'Chưa tính công nợ':s.collected?'Đã collect':card?'Chưa collect':'Xem phân bổ'}</small></span>${icon('chevron')}</button>`;}
function overview(){return head('Quỹ nhóm, rõ từng buổi.','Xem phần của mình. Cùng giữ mọi cuộc vui nhẹ nhàng.',true)+selector()+`<div class="overview-grid">${hero()}<section class="overview-aside"><div><p class="section-kicker">CÙNG CHƠI. CÙNG CHIA.</p><h2>${visibleMembers().length} người còn công nợ.</h2><p>Chỉ hiển thị phần chưa giải quyết.</p><div class="avatar-stack">${visibleMembers().slice(0,5).map(avatar).join('')}<span class="avatar">+${Math.max(visibleMembers().length-5,0)}</span></div></div><button class="text-button" data-action="members">Xem các thành viên ${icon('users')}</button></section></div>`+notice()+`<section><div class="section-head"><div><h2>${selected()?'Công nợ của '+esc(selected().name):'Công nợ thành viên'}</h2><p>Tính từ ${D.openCount} buổi chưa collect có đủ dữ liệu.</p></div></div>${memberPanel()}</section><div class="lower-grid"><section><div class="section-head"><h2>Các buổi chưa collect</h2><button class="text-button" data-action="sessions">Xem tất cả</button></div><div class="panel">${openSessions().filter(s=>!selected()||selected().sessions.includes(s.id)).slice(-3).reverse().map(s=>sessionRow(s)).join('')||'<div class="empty">Chưa có buổi liên quan.</div>'}</div></section><aside class="panel guide"><h2>Sổ quỹ hoạt động thế nào?</h2><div class="guide-step"><span class="step-no">1</span><div><strong>Tìm tên của bạn</strong><p>Xem phần phải chịu và tiền đã ứng.</p></div></div><div class="guide-step"><span class="step-no">2</span><div><strong>Đối chiếu từng buổi</strong><p>Chạm vào buổi để xem người tham gia.</p></div></div><div class="guide-step"><span class="step-no">3</span><div><strong>Chốt cùng admin</strong><p>Thanh toán được cập nhật qua Excel.</p></div></div></aside></div>`;}
function sessions(){return head('Mỗi buổi, một trang rõ ràng.','Chỉ các buổi chưa collect hoặc chưa cân; buổi đã xong được bỏ qua.')+`<div class="filterbar">${search('Tìm tên buổi hoặc mã…')}<div class="filter-group"><select id="category" aria-label="Loại hoạt động"><option value="all">Mọi hoạt động</option><option value="sport" ${state.category==='sport'?'selected':''}>Cầu lông</option><option value="food" ${state.category==='food'?'selected':''}>Ăn uống</option></select><select id="collection" aria-label="Trạng thái buổi"><option value="open" ${state.collection==='open'?'selected':''}>Chưa collect</option><option value="all" ${state.collection==='all'?'selected':''}>Tất cả buổi mở</option><option value="review" ${state.collection==='review'?'selected':''}>Cần kiểm tra</option></select></div></div><div id="session-results">${sessionList()}</div><div class="help-callout">${icon('info')} <strong>Ngày chưa có trong Excel được giữ nguyên là “Chưa có ngày”.</strong> Trạng thái collect được lấy từ file, chưa có chi tiết giao dịch thanh toán.</div>`;}
function sessionList(){const list=D.sessions.filter(s=>(state.category==='all'||s.category===state.category)&&(state.collection==='all'||state.collection==='open'&&!s.collected||state.collection==='closed'&&s.collected||state.collection==='review'&&(s.issues.length||s.pending))&&normalize(s.id+' '+s.title).includes(normalize(state.query))).reverse();return `<div class="section-head"><span class="count-label">${list.length} buổi</span><span class="count-label">Cập nhật theo Excel</span></div><div class="activity-list">${list.map(s=>`<article class="activity-card">${sessionRow(s,true)}</article>`).join('')||'<div class="panel empty">Không có buổi phù hợp.<button class="text-button" data-action="reset">Xóa bộ lọc</button></div>'}</div>`;}
function members(){return head('Những người cùng nhóm.','Chỉ hiển thị người còn phải đóng hoặc còn được nhận.',true)+notice()+memberPanel()+`<div class="help-callout">Đã thanh toán và không còn thấy tên? <button class="text-button" data-action="payments">Xem lịch sử thanh toán</button></div>`;}
function dataPage(){return head('Dữ liệu rõ, số tiền mới rõ.','Nguồn gốc, thời điểm cập nhật và những điểm cần đối chiếu.')+`<div class="data-layout"><section class="panel data-section"><h2>Thông tin bản dữ liệu</h2><div class="data-item"><span>Nguồn</span><strong>${esc(D.sourceTitle)}</strong></div><div class="data-item"><span>File cập nhật</span><strong>${stamp}</strong></div><div class="data-item"><span>Múi giờ</span><strong>TP.HCM · UTC+7</strong></div><div class="data-item"><span>Phạm vi</span><strong>${D.sessions.length} buổi mở · ${visibleMembers().length} người còn công nợ</strong></div><div class="data-item"><span>Đưa vào công nợ</span><strong>${D.openCount} buổi · ${money(D.total)}</strong></div><div class="data-item"><span>Đã nhận, admin xác nhận</span><strong>${money(D.received||0)}</strong></div><div class="data-item"><span>Miễn / clear nợ, không phải tiền thu</span><strong>${money(D.waived||0)}</strong></div><div class="data-item"><span>Trạng thái</span><strong>Tạm tính, chưa chốt sao kê</strong></div><a class="button" href="${esc(D.sourceUrl)}" target="_blank" rel="noopener noreferrer">${icon('file')}Mở file gốc</a><div class="dialog-section"><h3>Cách tính trong bản này</h3><p class="body-copy">Bỏ qua hoàn toàn buổi đã collect hoặc đã cân. Chỉ cộng buổi mở có hóa đơn lớn hơn 0 và dữ liệu phân bổ khớp. Người có số dư bằng 0 không xuất hiện trong danh sách công nợ. Chia nguyên đồng theo thứ tự danh sách trong file; phần dư 1đ phân lần lượt. Công nợ bằng phần phải chịu trừ tiền đã ứng. Không tự suy ra giao dịch thanh toán từ trạng thái collect.</p></div></section><section class="panel data-section"><h2>Cần đối chiếu <span class="badge warning">${D.issues.length}</span></h2>${D.issues.map(i=>`<div class="issue"><h3>${esc(i.title)}</h3><p>${esc(i.description)}</p>${D.sessions.some(s=>s.id===i.id)?`<button class="text-button" data-session="${i.id}">Xem chi tiết buổi</button>`:''}</div>`).join('')}</section></div><div class="help-callout"><strong>Cập nhật bằng Excel.</strong> Admin chỉnh file nguồn, gửi bản mới để cập nhật website. Bill và góp ý mới gửi riêng cho admin, không tự thay đổi công nợ. Thanh toán và dữ liệu đã duyệt được cập nhật qua Excel.</div>`;}

const formatDateOnly=value=>new Intl.DateTimeFormat('vi-VN',{day:'2-digit',month:'2-digit',year:'numeric',timeZone:'UTC'}).format(new Date(value+'T00:00:00Z'));
const paidDateLabel=p=>p.paidDate?(p.datePrecision==='approximate'?'Khoảng ':'')+formatDateOnly(p.paidDate):p.paidAt?new Intl.DateTimeFormat('vi-VN',{timeZone:D.timezone}).format(new Date(p.paidAt)):'Chưa rõ ngày chuyển';
const recordedLabel=p=>new Intl.DateTimeFormat('vi-VN',{day:'2-digit',month:'2-digit',year:'numeric',timeZone:D.timezone}).format(new Date(p.recordedAt));
function paymentRows(){const rows=(D.payments||[]).filter(p=>normalize(p.memberName).includes(normalize(state.query))).slice().sort((a,b)=>String(b.paidDate||b.recordedAt).localeCompare(String(a.paidDate||a.recordedAt)));return rows.length?rows.map(p=>{const m=D.members.find(m=>m.name===p.memberName);return '<article class="payment-row"><div class="payment-person"><button class="person-button" data-person="'+m.id+'">'+avatar(m)+'<span class="person-name">'+esc(p.memberName)+'<small>'+esc(paidDateLabel(p))+'</small></span></button><span class="badge credit">'+(m.balance===0?'Đã hết nợ':'Đã ghi nhận')+'</span></div><div class="payment-amount money">'+money(p.amount)+'</div><p class="payment-meta">Admin xác nhận '+esc(recordedLabel(p))+'</p>'+(m.waived?'<p class="payment-meta">Đã clear thêm '+money(m.waived)+' chênh lệch; không tính vào tiền nhận.</p>':'')+'<p class="payment-meta">'+(p.datePrecision==='approximate'?'Ngày chuyển ước tính, chưa có ngày chính xác.':'Ngày chuyển theo thông tin admin cung cấp.')+'</p><button class="text-button" data-person="'+m.id+'">Xem đối chiếu cá nhân</button></article>';}).join(''):'<div class="empty">Không có khoản thanh toán phù hợp.</div>';}
function paymentsPage(){const count=new Set((D.payments||[]).map(p=>p.memberName)).size;return head('Lịch sử thanh toán','Các khoản thành viên đã trả, được admin xác nhận.')+'<section class="payment-summary"><div><span>Đã nhận</span><strong class="money">'+money(D.received||0)+'</strong></div><div><span>Người đã thanh toán</span><strong>'+count+' người</strong></div></section><div class="notice">'+icon('info')+'<div>Ngày có chữ <strong>“Khoảng”</strong> là ước tính do admin cung cấp. Người đã hết nợ vẫn được giữ trong lịch sử này.</div></div><div class="filterbar">'+search('Tìm người đã thanh toán…')+'</div><section class="payment-grid" id="payment-results">'+paymentRows()+'</section>';}

function render(){nav();main.innerHTML=({overview,members,sessions,payments:paymentsPage,data:dataPage}[state.page]||overview)();document.title=navItems.find(n=>n[0]===state.page)[2]+' · AE48';}
function navigate(page){if(!navItems.some(n=>n[0]===page))page='overview';const changed=state.page!==page;state.page=page;state.query='';state.status='all';render();if(changed)window.scrollTo({top:0});}
function showModal(html){document.getElementById('dialog-content').innerHTML=html;if(!dialog.open)dialog.showModal();dialog.scrollTop=0;}
const modalHead=(title,sub)=>`<div class="dialog-head"><div><h2 id="dialog-title">${esc(title)}</h2><p>${esc(sub)}</p></div><button class="close" data-action="close" aria-label="Đóng chi tiết">${icon('close')}</button></div>`;
function showSession(id){const s=D.sessions.find(s=>s.id===id);if(!s)return;const invalid=s.issues.length||s.pending;showModal(modalHead(s.id+' · '+s.title,date(s)+' · '+(s.category==='sport'?'Cầu lông':'Ăn uống'))+`<div class="dialog-total"><p>Tổng chi theo Excel</p><div class="money">${s.pending?'Chờ hóa đơn':money(s.total)}</div><span class="badge ${invalid?'warning':''}">${sessionStatus(s)}</span></div>${invalid?`<div class="dialog-note">${s.pending?'Chưa có số tiền hóa đơn. Buổi này chưa được tính vào công nợ.':esc(s.issues.join(' '))+' Không đưa vào công nợ hiện tại.'}</div>`:''}<section class="dialog-section"><h3>Khoản chi & người ứng</h3>${s.costs.map(c=>`<div class="detail-line"><span>${esc(c.label)}<small>${esc(c.payer||'Chưa có người ứng')}</small></span><strong class="money">${money(c.amount)}</strong></div>`).join('')||'<p class="body-copy">File chưa có khoản chi.</p>'}</section><section class="dialog-section"><h3>${s.participants.length} người được đánh dấu tham gia</h3><div class="people-chips">${s.participants.map(n=>`<button data-person="${D.members.find(m=>m.name===n).id}">${esc(n)}</button>`).join('')||'<p class="body-copy">File chưa đánh dấu người tham gia.</p>'}</div></section>${!invalid?`<section class="dialog-section"><h3>Phân bổ chia đều${s.collected?' · tham khảo lịch sử':''}</h3>${s.participants.map(n=>`<div class="detail-line"><span>${esc(n)}</span><span class="money">${money(s.shares[n])}</span></div>`).join('')}</section>`:''}${s.note?`<div class="dialog-note">Ghi chú gốc: ${esc(s.note)}. Phân bổ lịch sử cần đọc cùng ghi chú này.</div>`:''}<div class="dialog-actions"><button class="button" data-feedback-session="${s.id}">Góp ý khoản chi</button><button class="button primary" data-submit-bill="${s.id}">Thêm bill buổi này</button></div><p class="body-copy" style="margin-top:22px">${s.collected?'“Đã collect” là trạng thái trong Excel, không phải bằng chứng thanh toán từng người.':'Số liệu tạm tính từ Excel. Các khoản đóng chưa phân bổ theo buổi được trừ trong tổng công nợ từng người.'}</p>`);}
function showPerson(id){const m=D.members.find(m=>m.id===id);if(!m)return;showModal(modalHead(m.name,m.guest?'Khách tham gia nhóm':'Thành viên AE48')+`<div class="dialog-total"><p>${m.balance<0?'Còn được nhận, tạm tính':m.balance>0?'Cần đóng, tạm tính':'Không có công nợ mở'}</p><div class="money ${m.balance<0?'balance-negative':''}">${money(m.balance)}</div></div><div class="balance-grid"><div class="balance-cell"><small>Phần phải chịu</small><div class="money">${money(m.share)}</div></div><div class="balance-cell"><small>Tiền đã ứng</small><div class="money">${money(m.advance)}</div></div></div><section class="dialog-section"><h3>${m.sessions.length} buổi · phát sinh trước thanh toán</h3>${m.sessions.map(id=>{const s=D.sessions.find(s=>s.id===id);const advance=s.costs.filter(c=>c.payer===m.name).reduce((a,c)=>a+c.amount,0);const b=(s.shares[m.name]||0)-advance;return `<button class="session-row" data-session="${id}" style="padding-left:0;padding-right:0"><span><span class="session-title">${id} · ${esc(s.title)}</span><span class="session-meta" style="display:block">Chịu ${money(s.shares[m.name]||0)} · Ứng ${money(advance)}</span></span><span class="session-value money ${b<0?'balance-negative':''}">${b<0?'− ':''}${money(b)}</span></button>`;}).join('')||'<p class="body-copy">Không có phát sinh từ các buổi mở đủ dữ liệu.</p>'}</section>${m.paid?`<section class="dialog-section"><h3>Khoản đóng đã xác nhận</h3>${(D.payments||[]).filter(p=>p.memberName===m.name).map(p=>`<div class="detail-line"><span>${esc(paidDateLabel(p))}<small>Admin ghi nhận ${esc(recordedLabel(p))} · Chưa gắn buổi cụ thể</small></span><strong class="money">− ${money(p.amount)}</strong></div>`).join('')}</section>`:''}${m.waived?`<section class="dialog-section"><h3>Điều chỉnh miễn phần còn lại</h3><div class="detail-line"><span>Admin clear nợ<small>Không phải tiền đã thu</small></span><strong class="money">− ${money(m.waived)}</strong></div></section>`:''}<div class="dialog-note">Số còn lại đã trừ khoản đóng và điều chỉnh được admin xác nhận. Khoản đóng chưa gắn buổi được trừ ở tổng công nợ cá nhân; các dòng buổi phía trên là phát sinh trước thanh toán.</div><div class="dialog-actions"><button class="button primary" data-select="${m.id}">Xem tổng quan của ${esc(m.name)}</button><button class="button" data-copy="${m.id}">${icon('copy')}Sao chép đối chiếu</button></div>`);}
let toastTimer;function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),2800);}
function exportCSV(){const rows=[['Thành viên','Phải chịu (VND)','Đã ứng (VND)','Đã đóng (VND)','Miễn / clear nợ (VND)','Cần đóng tạm tính (VND)','Được nhận tạm tính (VND)','Số buổi','Nguồn cập nhật'],...visibleMembers().map(m=>[m.name,m.share,m.advance,m.paid||0,m.waived||0,Math.max(m.balance,0),Math.max(-m.balance,0),m.sessions.length,stamp])];const csv='\ufeff'+rows.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='AE48-cong-no-tam-tinh-2026-11-22.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Đã xuất bản đối chiếu CSV');}
function updateResults(){const target=state.page==='sessions'?'session-results':state.page==='payments'?'payment-results':'member-results';const results=document.getElementById(target);if(results)results.innerHTML=state.page==='sessions'?sessionList():state.page==='payments'?paymentRows():memberList();}
document.addEventListener('input',e=>{if(e.target.id==='search'){state.query=e.target.value;updateResults();}});
document.addEventListener('change',e=>{if(e.target.id==='member-select'){state.member=e.target.value;try{localStorage.setItem('ae48-person',state.member);}catch{}state.query='';state.status='all';render();}if(['category','collection'].includes(e.target.id)){state[e.target.id]=e.target.value;updateResults();}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.person){showPerson(b.dataset.person);return;}if(b.dataset.session){showSession(b.dataset.session);return;}if(b.dataset.status){state.status=b.dataset.status;document.querySelectorAll('[data-status]').forEach(el=>{el.classList.toggle('active',el.dataset.status===state.status);el.setAttribute('aria-pressed',String(el.dataset.status===state.status));});updateResults();return;}if(b.dataset.select){state.member=b.dataset.select;try{localStorage.setItem('ae48-person',state.member);}catch{}dialog.close();if(location.hash==='#overview')navigate('overview');else location.hash='overview';return;}if(b.dataset.copy){const m=D.members.find(m=>m.id===b.dataset.copy);const t=`AE48 · ${m.name}\n${m.balance<0?'Được nhận':m.balance>0?'Cần đóng':'Không phát sinh'} (tạm tính): ${money(m.balance)}\nPhải chịu: ${money(m.share)}\nĐã ứng: ${money(m.advance)}\nĐã đóng: ${money(m.paid||0)}\nMiễn / clear nợ: ${money(m.waived||0)}\nCập nhật: ${stamp}. Chỉ tính các khoản đóng được admin xác nhận.`;try{await navigator.clipboard.writeText(t);toast('Đã sao chép bản đối chiếu');}catch{toast('Trình duyệt chưa cho phép sao chép.');}return;}const a=b.dataset.action;if(a==='close')dialog.close();else if(a==='export')exportCSV();else if(a==='reset'){state.query='';state.status='all';state.category='all';state.collection='all';render();}else if(['overview','sessions','members','payments','data'].includes(a)){if(dialog.open)dialog.close();if(location.hash==='#'+a)navigate(a);else location.hash=a;}});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));navigate(location.hash.slice(1)||'overview');
})();
